async fn put_content(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
    body: axum::body::Bytes,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    let (d, _) = s
        .stores
        .core
        .get_doc(&u.claims.org, id)
        .await
        .map_err(|_| AppError::NotFound("document".into()))?;
    portal_doc_guard(&s, &u, &d).await?;
    if body.len() as u64 != d.size {
        return Err(AppError::Validation("size mismatch".into()));
    }
    if let Some(l) = s
        .stores
        .ops
        .dlock_get(&u.claims.org, id)
        .await
        .map_err(map_store)?
    {
        if l.holder != u.claims.sub {
            return Err(AppError::Conflict("locked by other".into()));
        }
    }
    let sha = legalrust_document::sha256_hex(&body);
    if sha != d.sha {
        return Err(AppError::Validation("sha256 mismatch".into()));
    }
    let key = format!("docs/{}/content", id);
    s.stores.objects.put(&key, &body).await?;
    let v = s
        .stores
        .core
        .add_version(&u.claims.org, id, &key, &sha)
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    // Search queue trigger (F-D04-036): text uploads index themselves into
    // the RAG chunks immediately; image/scanned OCR stays a manual job
    // (engine-dependent). Best-effort: never fail the upload itself.
    if d.mime.starts_with("text/") {
        if let Ok(text) = String::from_utf8(body.to_vec()) {
            let chunks = legalrust_rag::chunk_text(&text, 800, 100);
            let _ = s.stores.ops.rag_put(id, &chunks).await;
        }
    }
    // Scanned-document ingestion (F-D04-025): image uploads auto-join the
    // OCR queue with a general doctype; processing still needs the engine.
    if d.mime.starts_with("image/") {
        let _ = s.stores.ops.ocr_create(&u.claims.org, id, "general").await;
    }
    Ok(Json(json!({"version": v.version_no})))
}
async fn get_content(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
) -> Result<impl IntoResponse, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Download)?;
    let (d, vs) = s
        .stores
        .core
        .get_doc(&u.claims.org, id)
        .await
        .map_err(|_| AppError::NotFound("document".into()))?;
    portal_doc_guard(&s, &u, &d).await?;
    let v = vs
        .last()
        .ok_or_else(|| AppError::NotFound("content".into()))?;
    let bytes = s.stores.objects.get(&v.object_key).await?;
    let mut h = HeaderMap::new();
    h.insert(
        "content-type",
        d.mime
            .parse()
            .unwrap_or(HeaderValue::from_static("application/octet-stream")),
    );
    Ok((StatusCode::OK, h, bytes))
}

/// Tamper-evident evidence check (F-D22-027): recompute SHA-256 of every
/// stored version and compare against the pinned hash recorded at upload.
/// Any mismatch (or missing object) is reported per version and audited.
fn verify_rows(rows: &[(i64, String, Option<String>)]) -> (bool, i64) {
    let mut bad = 0i64;
    for (_, expected, actual) in rows {
        if actual.as_deref() != Some(expected.as_str()) {
            bad += 1;
        }
    }
    (bad == 0, bad)
}
async fn doc_verify(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let (d, vs) = s
        .stores
        .core
        .get_doc(&u.claims.org, id)
        .await
        .map_err(|_| AppError::NotFound("document".into()))?;
    portal_doc_guard(&s, &u, &d).await?;
    let mut checks: Vec<(i64, String, String, Option<String>)> = Vec::new();
    for v in &vs {
        let actual = match s.stores.objects.get(&v.object_key).await {
            Ok(b) => Some(legalrust_document::sha256_hex(&b)),
            Err(_) => None,
        };
        checks.push((v.version_no, v.object_key.clone(), v.sha.clone(), actual));
    }
    let (ok, bad) = verify_rows(
        &checks
            .iter()
            .map(|(a, _, c, d)| (*a, c.clone(), d.clone()))
            .collect::<Vec<_>>(),
    );
    let rows: Vec<Value> = checks
        .iter()
        .map(|(no, key, exp, act)| {
            json!({"version": no, "object_key": key, "expected": exp, "actual": act,
                    "ok": act.as_deref() == Some(exp.as_str())})
        })
        .collect();
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: format!("document.verified:{bad}"),
            entity: "document".into(),
            entity_id: id,
            ip: None,
        },
    )
    .await;
    Ok(Json(
        json!({"id": d.id, "versions": rows.len() as i64, "bad": bad,
                   "ok": ok, "rows": rows}),
    ))
}

#[cfg(test)]
mod verify_tests {
    use super::verify_rows;
    #[test]
    fn intact_store_passes() {
        assert_eq!(
            verify_rows(&[(1, "k".into(), Some("abc".into()))]),
            (false, 1)
        );
        assert_eq!(
            verify_rows(&[
                (1, "abc".into(), Some("abc".into())),
                (2, "def".into(), Some("def".into()))
            ]),
            (true, 0)
        );
        assert_eq!(verify_rows(&[]), (true, 0));
    }
    #[test]
    fn mismatch_and_missing_flagged() {
        assert_eq!(
            verify_rows(&[(1, "e".into(), Some("x".into()))]),
            (false, 1)
        );
        assert_eq!(verify_rows(&[(1, "e".into(), None)]), (false, 1));
        assert_eq!(
            verify_rows(&[(1, "e".into(), Some("e".into())), (2, "f".into(), None)]),
            (false, 1)
        );
    }
}

