// ---------- property slice: certificate authenticity verdict ----------
// Full certificate-authenticity flow (F-D13-003): deed-scoped verdict over
// live records — register completeness, verified consents, pinned scans,
// stored AJB draft, answered BPN verification. Parcel-scoped checks
// (disputes, boundaries, PBB) stay on their own per-bidang cards and are
// reported as pointers, not gates, since deeds key objects by free text.
async fn ppat_authenticity(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let ops = &s.stores.ops;
    let org = &u.claims.org;
    let r = ops
        .ppat_list(org)
        .await
        .map_err(map_store)?
        .into_iter()
        .find(|x| x.id == id)
        .ok_or(AppError::NotFound("ppat".into()))?;
    let mut checks: Vec<Value> = Vec::new();
    let mut push = |key: &str, label: &str, pass: bool, detail: String| {
        checks.push(json!({"key": key, "label": label, "pass": pass, "detail": detail}));
    };
    push(
        "fields",
        "Register lengkap (nomor, penjual, pembeli, objek)",
        !r.number.trim().is_empty()
            && !r.party_seller.trim().is_empty()
            && !r.party_buyer.trim().is_empty()
            && !r.object_desc.trim().is_empty(),
        format!("akta {}", r.number),
    );
    let consents = ops.dconsent_list(org, id).await.map_err(map_store)?;
    let unverified = consents.iter().filter(|c| !c.verified).count();
    push(
        "consents",
        "Seluruh persetujuan terverifikasi",
        !consents.is_empty() && unverified == 0,
        format!(
            "{} tercatat, {} belum verifikasi",
            consents.len(),
            unverified
        ),
    );
    let scans = ops.clink_list(org, id).await.map_err(map_store)?;
    push(
        "vault",
        "Pindaian sertifikat terarsip di brankas",
        !scans.is_empty(),
        format!("{} dokumen tertaut", scans.len()),
    );
    let drafts = ops.ajbd_list(org, id).await.map_err(map_store)?;
    push(
        "draft",
        "Draf AJB tersimpan",
        !drafts.is_empty(),
        format!("{} draf", drafts.len()),
    );
    let bpns = ops
        .bpn_list(org, Some("verification"))
        .await
        .map_err(map_store)?;
    let answered = bpns.iter().find(|b| b.status == "answered");
    push(
        "bpn",
        "Verifikasi BPN terjawab",
        answered.is_some(),
        answered
            .map(|b| format!("{} @ {}", b.ref_no, b.office))
            .unwrap_or_else(|| "belum ada jawaban tercatat".into()),
    );
    let verdict = checks.iter().all(|c| c["pass"].as_bool().unwrap_or(false));
    let reasons: Vec<String> = checks
        .iter()
        .filter(|c| !c["pass"].as_bool().unwrap_or(false))
        .map(|c| c["label"].as_str().unwrap_or("?").to_string())
        .collect();
    Ok(Json(
        json!({"id": r.id, "number": r.number, "verdict": verdict, "checks": checks, "reasons": reasons,
        "parcel_note": "Cek sengketa/batas/PBB per bidang pada kartu terkait (kunci objek akta berupa teks bebas)."}),
    ))
}
// ---------- end property slice: certificate authenticity verdict ----------

