// ---------- compliance slice: protocol retention schedule + AML scoring ----------
// Protocol retention schedule (F-D11-013): 25-year default horizon over
// protocol_register entry dates (lexicographic YYYY-MM-DD compare, same as
// the SKMHT expiry monitor). Pure date math, no external calls.
#[derive(Debug, Deserialize)]
struct PretQ {
    years: Option<i64>,
}
async fn protocol_retention_due(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<PretQ>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let years = q.years.unwrap_or(25);
    if !(1..=100).contains(&years) {
        return Err(AppError::Validation("years 1..100".into()));
    }
    let cutoff = (chrono::Utc::now().naive_utc().date() - chrono::Duration::days(365 * years))
        .format("%Y-%m-%d")
        .to_string();
    let v = s
        .stores
        .ops
        .preg_list(&u.claims.org)
        .await
        .map_err(map_store)?;
    let due: Vec<Value> = v
        .iter()
        .filter(|r| !r.entry_date.trim().is_empty() && r.entry_date.as_str() <= cutoff.as_str())
        .map(|r| json!({"id": r.id, "entry_date": r.entry_date, "book_ref": r.book_ref, "deed_no": r.deed_no, "party": r.party}))
        .collect();
    Ok(Json(
        json!({"years": years, "cutoff": cutoff, "due_count": due.len(), "due": due}),
    ))
}
// AML/CFT risk scoring (F-D11-015): documented heuristic over live ledgers.
// base 10 + corporate 20 + 5/matter (cap 25) + 10 per >=Rp100jt open balance
// (cap 30); bands low<30 / medium<60 / high>=60. Screening input, not a verdict.
/// Shared AML heuristic (also feeds risk routing): returns (score, band).
fn aml_score_for(kind: &str, matter_count: i64, big_open: i64) -> (i64, &'static str, Vec<String>) {
    let mut factors: Vec<String> = vec!["basis 10".into()];
    let mut score = 10i64;
    if kind == "corporate" {
        score += 20;
        factors.push("korporasi +20".into());
    }
    let mpts = (matter_count * 5).min(25);
    score += mpts;
    factors.push(format!("{matter_count} perkara +{mpts}"));
    let bpts = (big_open * 10).min(30);
    score += bpts;
    factors.push(format!("{big_open} tagihan >=Rp100jt +{bpts}"));
    let band = if score < 30 {
        "low"
    } else if score < 60 {
        "medium"
    } else {
        "high"
    };
    (score, band, factors)
}
async fn aml_scores(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let clients = s
        .stores
        .core
        .list_clients(&u.claims.org)
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    let matters = visible_matters(&s, &u).await?;
    let open = s
        .stores
        .ops
        .inv_list_open(&u.claims.org)
        .await
        .map_err(map_store)?;
    let bal_by_matter: std::collections::HashMap<i64, i64> =
        open.into_iter().map(|r| (r.matter_id, r.balance)).collect();
    let rows: Vec<Value> = clients
        .iter()
        .map(|c| {
            let cm: Vec<&MatterRow> = matters.iter().filter(|m| m.client_id == Some(c.id)).collect();
            let open_balance: i64 = cm.iter().filter_map(|m| bal_by_matter.get(&m.id)).sum();
            let big = cm.iter().filter(|m| bal_by_matter.get(&m.id).map(|b| *b >= 100_000_000).unwrap_or(false)).count() as i64;
            let (score, band, factors) = aml_score_for(&c.kind, cm.len() as i64, big);
            json!({"client_id": c.id, "name": c.display_name, "kind": c.kind, "matters": cm.len(), "open_balance": open_balance, "score": score, "band": band, "factors": factors})
        })
        .collect();
    Ok(Json(
        json!({"weights": "basis 10 + korporasi 20 + 5/perkara (maks 25) + 10/tagihan-besar (maks 30)", "rows": rows}),
    ))
}
// ---------- end compliance slice: retention schedule + AML ----------

