// MPN supervision response pack (F-D12-006): protocol archive position +
// pending handoffs + latest property audit + active retention rules.
async fn mpn_pack(State(s): State<FullState>, headers: HeaderMap) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let ops = &s.stores.ops;
    let org = &u.claims.org;
    let regs = ops.preg_list(org).await.map_err(map_store)?;
    let preqs = ops.preq_list(org).await.map_err(map_store)?;
    let pending_purges = preqs
        .iter()
        .filter(|r| r.status == "requested" || r.status == "approved")
        .count();
    let rules = ops.rrule_list(org).await.map_err(map_store)?;
    let active_rules = rules.iter().filter(|r| r.active).count();
    let mut recent = ops
        .audit_list(org, None, None, 50)
        .await
        .map_err(map_store)?;
    recent.retain(|a| a.action.starts_with("property.") || a.action.starts_with("retention."));
    recent.truncate(50);
    Ok(Json(
        json!({"generated_at": chrono::Utc::now().format("%Y-%m-%d %H:%M:%S").to_string(),
        "protocol_entries": regs.len(),
        "pending_purges": pending_purges,
        "active_retention_rules": active_rules,
        "recent_property_events": recent.iter().map(|a| json!({"id": a.id, "actor": a.actor, "action": a.action, "entity": a.entity, "entity_id": a.entity_id, "created": a.created})).collect::<Vec<_>>()}),
    ))
}
// ---------- end office slice: report packs ----------

// ---------- approval slice: SLA + conflict detection ----------
// Approval SLA (F-D09-005): age of open requests against warn/breach hour
// thresholds. Pure derivation over created timestamps; escalation = the
// breach flag surfacing in UI + audit trail below (no silent auto-decision).
#[derive(Debug, Deserialize)]
struct SlaQ {
    warn_hours: Option<i64>,
    breach_hours: Option<i64>,
}
fn approval_age_hours(created: &str) -> Option<i64> {
    let dt = chrono::NaiveDateTime::parse_from_str(created.trim(), "%Y-%m-%d %H:%M:%S").ok()?;
    let age = chrono::Utc::now().naive_utc() - dt;
    Some(age.num_seconds().div_euclid(3600))
}
async fn approval_sla(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<SlaQ>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let warn = q.warn_hours.unwrap_or(24).clamp(1, 720);
    let breach = q.breach_hours.unwrap_or(72).clamp(1, 2160);
    let mut rows: Vec<Value> = Vec::new();
    for st in ["pending", "needs_rework"] {
        let v = s
            .stores
            .ops
            .appr_list(&u.claims.org, Some(st))
            .await
            .map_err(map_store)?;
        for r in v {
            let age = approval_age_hours(&r.created).unwrap_or(0);
            let state = if age >= breach {
                "breach"
            } else if age >= warn {
                "warn"
            } else {
                "ok"
            };
            rows.push(json!({"id": r.id, "title": r.title, "entity": r.entity, "entity_id": r.entity_id, "status": r.status, "age_hours": age, "sla": state}));
        }
    }
    rows.sort_by_key(|r| -r["age_hours"].as_i64().unwrap_or(0));
    Ok(Json(
        json!({"warn_hours": warn, "breach_hours": breach, "rows": rows}),
    ))
}
// Approval conflict detection (F-D09-033): two or more open requests
// against the same entity instance. Advisory — resolution stays manual.
async fn approval_conflicts(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let mut open: Vec<(String, i64, i64, String)> = Vec::new();
    for st in ["pending", "needs_rework"] {
        let v = s
            .stores
            .ops
            .appr_list(&u.claims.org, Some(st))
            .await
            .map_err(map_store)?;
        for r in v {
            open.push((r.entity, r.entity_id, r.id, r.title));
        }
    }
    let mut groups: std::collections::BTreeMap<(String, i64), Vec<Value>> =
        std::collections::BTreeMap::new();
    for (entity, eid, id, title) in open {
        groups
            .entry((entity, eid))
            .or_default()
            .push(json!({"id": id, "title": title}));
    }
    let conflicts: Vec<Value> = groups
        .into_iter()
        .filter(|(_, v)| v.len() > 1)
        .map(|((entity, eid), v)| json!({"entity": entity, "entity_id": eid, "count": v.len(), "requests": v}))
        .collect();
    Ok(Json(
        json!({"conflict_count": conflicts.len(), "conflicts": conflicts}),
    ))
}
// ---------- end approval slice: SLA + conflicts ----------

// ---------- approval slice: controlled bulk decide ----------
// Decidable inbox (F-D09-007): open steps the caller may decide right now
// (role gate or delegated authority), backing the bulk checkbox UI.
async fn appr_decidable(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let mut rows: Vec<Value> = Vec::new();
    for st in ["pending", "needs_rework"] {
        let v = s
            .stores
            .ops
            .appr_list(&u.claims.org, Some(st))
            .await
            .map_err(map_store)?;
        for r in v {
            let (_, steps) = s
                .stores
                .ops
                .appr_get(&u.claims.org, r.id)
                .await
                .map_err(map_store)?;
            for step in steps {
                if step.status != "pending" {
                    continue;
                }
                let may = if appr_may_decide_delegated(&s, &u, &step.role).await {
                    true
                } else {
                    appr_may_decide(&u, &step.role)
                };
                if may {
                    rows.push(json!({"id": r.id, "title": r.title, "entity": r.entity, "step_no": step.step_no, "role": step.role}));
                }
            }
        }
    }
    rows.sort_by_key(|r| r["id"].as_i64().unwrap_or(0));
    Ok(Json(json!({"rows": rows})))
}
#[derive(Debug, Deserialize)]
struct BulkItem {
    id: i64,
    step_no: i64,
    decision: String,
    comment: Option<String>,
}
#[derive(Debug, Deserialize)]
struct BulkDecideReq {
    items: Vec<BulkItem>,
}
async fn appr_decide_bulk(
    State(s): State<FullState>,
    headers: HeaderMap,
    Json(b): Json<BulkDecideReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Approve)?;
    freeze_guard(&s, &u.claims.org).await?;
    if b.items.is_empty() || b.items.len() > 50 {
        return Err(AppError::Validation("items 1..50".into()));
    }
    if b.items
        .iter()
        .any(|it| it.comment.as_deref().is_some_and(|c| c.len() > 2000))
    {
        return Err(AppError::Validation("comment".into()));
    }
    // Per-item role gate BEFORE touching the store (same rule as single decide).
    for it in &b.items {
        if !["approve", "reject", "rework"].contains(&it.decision.trim()) {
            return Err(AppError::Validation("decision".into()));
        }
        let (_, steps) = s
            .stores
            .ops
            .appr_get(&u.claims.org, it.id)
            .await
            .map_err(map_store)?;
        let step = steps
            .iter()
            .find(|x| x.step_no == it.step_no)
            .ok_or_else(|| AppError::NotFound("step".into()))?;
        if !appr_may_decide_delegated(&s, &u, &step.role).await && !appr_may_decide(&u, &step.role)
        {
            return Err(AppError::Forbidden);
        }
    }
    idem_guard(&s, &headers, &u.claims.org, "appr_decide_bulk").await?;
    let items: Vec<(i64, i64, String, Option<String>)> = b
        .items
        .iter()
        .map(|it| {
            (
                it.id,
                it.step_no,
                it.decision.trim().to_string(),
                it.comment.clone(),
            )
        })
        .collect();
    let done = s
        .stores
        .ops
        .appr_decide_bulk(&u.claims.org, &u.claims.sub, &items)
        .await
        .map_err(map_store)?;
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: "approval.bulk_decided".into(),
            entity: "approval".into(),
            entity_id: done.len() as i64,
            ip: None,
        },
    )
    .await;
    for it in &b.items {
        receipt_record(
            &s,
            &u.claims.org,
            it.id,
            it.step_no,
            it.decision.trim(),
            &u.claims.sub,
        )
        .await;
    }
    Ok(Json(json!({"decided": done.len(),
        "rows": done.iter().map(|r| json!({"req": r.req, "step_no": r.step_no, "status": r.status})).collect::<Vec<_>>()})))
}
// ---------- end approval slice: controlled bulk decide ----------

// ---------- approval slice: decision simulation ----------
// Dry-run decision preview (F-D09-034): runs every gate and state check
// the real decide path would run, without mutating anything.
#[derive(Debug, Deserialize)]
struct SimulateReq {
    step_no: i64,
    decision: String,
}
async fn appr_simulate(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
    Json(b): Json<SimulateReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    let mut checks: Vec<Value> = Vec::new();
    let mut push = |key: &str, label: &str, pass: bool, detail: String| {
        checks.push(json!({"key": key, "label": label, "pass": pass, "detail": detail}));
    };
    if !["approve", "reject", "rework"].contains(&b.decision.trim()) {
        return Err(AppError::Validation("decision".into()));
    }
    let (req, steps) = s
        .stores
        .ops
        .appr_get(&u.claims.org, id)
        .await
        .map_err(map_store)?;
    push(
        "open",
        "Permintaan masih terbuka",
        ["pending", "needs_rework"].contains(&req.status.as_str()),
        format!("status: {}", req.status),
    );
    let step = steps.iter().find(|x| x.step_no == b.step_no);
    push(
        "step",
        "Tahap ditemukan",
        step.is_some(),
        format!("tahap {}", b.step_no),
    );
    let max_no = steps.iter().map(|x| x.step_no).max().unwrap_or(0);
    if let Some(st) = step {
        let role_ok = if appr_may_decide_delegated(&s, &u, &st.role).await {
            true
        } else {
            authorize(&u, Permission::Approve).is_ok() && appr_may_decide(&u, &st.role)
        };
        push(
            "role",
            "Berhak memutuskan tahap ini",
            role_ok,
            format!("peran tahap: {}", st.role),
        );
        let seq_ok = st.status == "pending"
            && steps
                .iter()
                .all(|x| x.step_no >= b.step_no || x.status == "approved");
        push(
            "sequence",
            "Tahap pending & tahap awal lolos",
            seq_ok,
            format!("status tahap: {}", st.status),
        );
    }
    let ok = checks.iter().all(|c| c["pass"].as_bool().unwrap_or(false));
    let outcome = if !ok {
        "blocked".to_string()
    } else {
        match b.decision.trim() {
            "approve" if b.step_no == max_no => "approved".into(),
            "approve" => "stays_open".into(),
            "reject" => "rejected".into(),
            _ => "needs_rework".into(),
        }
    };
    Ok(Json(
        json!({"id": req.id, "ok": ok, "outcome": outcome, "checks": checks}),
    ))
}
// ---------- end approval slice: simulation ----------

// ---------- approval slice: attachment review + archive ----------
// Attachment review (F-D09-011): documents pinned to the matter behind an
// approval request (deed/invoice resolve through their matter_id).
async fn appr_attachments(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let (req, _) = s
        .stores
        .ops
        .appr_get(&u.claims.org, id)
        .await
        .map_err(map_store)?;
    let matter_id: i64 = match req.entity.as_str() {
        "matter" => req.entity_id,
        "deed" => {
            s.stores
                .ops
                .deed_list(&u.claims.org)
                .await
                .map_err(map_store)?
                .into_iter()
                .find(|d| d.id == req.entity_id)
                .ok_or_else(|| AppError::NotFound("deed".into()))?
                .matter_id
        }
        "invoice" => {
            s.stores
                .ops
                .inv_get(&u.claims.org, req.entity_id)
                .await
                .map_err(map_store)?
                .0
                .matter_id
        }
        "document" => s
            .stores
            .core
            .get_doc(&u.claims.org, req.entity_id)
            .await
            .map_err(|_| AppError::NotFound("document".into()))?
            .0
            .matter_id
            .unwrap_or(0),
        _ => return Err(AppError::Validation("entity".into())),
    };
    let docs = s
        .stores
        .core
        .list_docs(&u.claims.org, Some(matter_id))
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    Ok(Json(
        json!({"id": req.id, "entity": req.entity, "matter_id": matter_id,
        "docs": docs.iter().map(|d| json!({"id": d.id, "name": d.name})).collect::<Vec<_>>()}),
    ))
}
// Approval archive & retrieval (F-D09-031): decided requests, newest first.
#[derive(Debug, Deserialize)]
struct ArchiveQ {
    status: Option<String>,
}
async fn appr_archive(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<ArchiveQ>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let statuses: Vec<&str> = match q.status.as_deref() {
        Some(st) if ["approved", "rejected", "revoked"].contains(&st) => vec![st],
        Some(_) => return Err(AppError::Validation("status".into())),
        None => vec!["approved", "rejected", "revoked"],
    };
    let mut rows: Vec<Value> = Vec::new();
    for st in statuses {
        let v = s
            .stores
            .ops
            .appr_list(&u.claims.org, Some(st))
            .await
            .map_err(map_store)?;
        for r in v {
            rows.push(json!({"id": r.id, "title": r.title, "entity": r.entity, "entity_id": r.entity_id, "status": r.status, "created": r.created}));
        }
    }
    rows.sort_by_key(|r| -r["id"].as_i64().unwrap_or(0));
    rows.truncate(200);
    Ok(Json(json!({"rows": rows})))
}
// ---------- end approval slice: attachments + archive ----------

