/// Executive summary pack (F-D20-039): one JSON snapshot across modules.
async fn executive_summary(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let org = &u.claims.org;
    let clients = s
        .stores
        .core
        .list_clients(org)
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    let matters = visible_matters(&s, &u).await?;
    let deeds = s.stores.ops.deed_list(org).await.map_err(map_store)?;
    let open_inv = s.stores.ops.inv_list_open(org).await.map_err(map_store)?;
    let open_bal: i64 = open_inv.iter().map(|r| r.balance).sum();
    let pending_appr = s
        .stores
        .ops
        .appr_list(org, Some("pending"))
        .await
        .map_err(map_store)?;
    let due = s
        .stores
        .core
        .task_due_list(org, 1000)
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let overdue = due
        .iter()
        .filter(|t| t.status != "done" && t.due.as_deref().is_some_and(|d| d < now.as_str()))
        .count();
    let obligations = s
        .stores
        .ops
        .pdp_obligation_list(org, Some("open"))
        .await
        .map_err(map_store)?;
    Ok(Json(json!({
        "clients": clients.len(), "matters": matters.len(), "deeds": deeds.len(),
        "open_invoices": open_inv.len(), "open_balance": open_bal,
        "pending_approvals": pending_appr.len(), "open_obligations": obligations.len(),
        "tasks_due_tracked": due.len(), "tasks_overdue": overdue,
    })))
}
/// Segregation-of-duties conflict check (F-D14-038): report risky permission
/// pairs held by one user; assignment of a conflicting role is blocked unless
/// explicitly acknowledged (audited override).
#[derive(Debug, Deserialize)]
struct SodQ {
    user: Option<String>,
    /// What-if role to simulate (no side effects).
    role: Option<String>,
}
/// Segregation-of-duties conflict pairs (F-D14-038): permission pairs no
/// single user should hold without explicit acknowledgment.
const SOD_PAIRS: &[(&str, &str, &str)] = &[
    (
        "Assign",
        "Download",
        "dapat memberi hak lalu mengunduh dokumen",
    ),
    (
        "Sign",
        "Verify",
        "menandatangani lalu memverifikasi sendiri",
    ),
    ("Create", "Approve", "membuat lalu menyetujui sendiri"),
];
fn sod_conflicts_for(perms: &[String]) -> Vec<serde_json::Value> {
    let has = |p: &str| perms.iter().any(|x| x == p);
    SOD_PAIRS
        .iter()
        .filter(|(a, b, _)| has(a) && has(b))
        .map(|(a, b, why)| json!({"pair": [a, b], "reason": why}))
        .collect()
}
fn role_permissions_of(role: &str) -> Vec<String> {
    match legalrust_domain::Role::parse(role) {
        Some(r) => legalrust_authorization::permissions(r)
            .iter()
            .map(|p| format!("{p:?}"))
            .collect(),
        None => Vec::new(),
    }
}
async fn sod_check(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<SodQ>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Assign)?;
    let uid = q.user.as_deref().unwrap_or(&u.claims.sub);
    let target = s
        .stores
        .users
        .get_user(uid)
        .await
        .map_err(map_store)?
        .ok_or_else(|| AppError::NotFound("user".into()))?;
    if target.org_id != u.claims.org {
        return Err(AppError::NotFound("user".into()));
    }
    let roles = s
        .stores
        .users
        .user_roles(&target.id)
        .await
        .map_err(map_store)?;
    let mut perms: Vec<String> = Vec::new();
    for r in &roles {
        for p in role_permissions_of(r) {
            if !perms.contains(&p) {
                perms.push(p);
            }
        }
    }
    // What-if simulation (no side effects): conflicts if `role` were added.
    if let Some(add) = q.role.as_deref() {
        for p in role_permissions_of(add) {
            if !perms.contains(&p) {
                perms.push(p);
            }
        }
    }
    let conflicts = sod_conflicts_for(&perms);
    Ok(Json(
        json!({"user": target.id, "permissions": perms, "conflicts": conflicts}),
    ))
}
