#[derive(Debug, Deserialize)]
struct AuditQ {
    entity: Option<String>,
    actor: Option<String>,
    limit: Option<i64>,
}
async fn audit_list(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<AuditQ>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    let allowed = u
        .claims
        .roles
        .iter()
        .filter_map(|r| legalrust_domain::Role::parse(r))
        .any(|r| {
            matches!(
                r,
                legalrust_domain::Role::SuperAdmin
                    | legalrust_domain::Role::OrgOwner
                    | legalrust_domain::Role::OfficeAdmin
                    | legalrust_domain::Role::Auditor
            )
        });
    if !allowed {
        return Err(AppError::Forbidden);
    }
    let v = s
        .stores
        .ops
        .audit_list(
            &u.claims.org,
            q.entity.as_deref(),
            q.actor.as_deref(),
            q.limit.unwrap_or(100).clamp(1, 500),
        )
        .await
        .map_err(map_store)?;
    Ok(Json(json!(v.iter().map(|a| json!({"id": a.id, "actor": a.actor, "action": a.action, "entity": a.entity, "entity_id": a.entity_id, "created": a.created})).collect::<Vec<_>>())))
}

/// Audit hash-chain verification (F-D22-026): recompute the tenant chain and
/// report breakage. Legacy pre-chain rows are counted, never mutated.
async fn audit_verify(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    let allowed = u
        .claims
        .roles
        .iter()
        .filter_map(|r| legalrust_domain::Role::parse(r))
        .any(|r| {
            matches!(
                r,
                legalrust_domain::Role::SuperAdmin
                    | legalrust_domain::Role::OrgOwner
                    | legalrust_domain::Role::OfficeAdmin
                    | legalrust_domain::Role::Auditor
            )
        });
    if !allowed {
        return Err(AppError::Forbidden);
    }
    let v = s
        .stores
        .ops
        .audit_list(&u.claims.org, None, None, 1_000_000)
        .await
        .map_err(map_store)?;
    let mut rows: Vec<legalrust_audit::ChainRow> = v
        .into_iter()
        .map(|a| legalrust_audit::ChainRow {
            id: a.id,
            tenant: a.tenant,
            actor: a.actor,
            action: a.action,
            entity: a.entity,
            entity_id: a.entity_id,
            before: a.before_hash,
            after: a.after_hash,
        })
        .collect();
    rows.sort_by_key(|r| r.id);
    match legalrust_audit::verify_chain(&rows) {
        Ok((checked, legacy)) => Ok(Json(
            json!({"ok": true, "checked": checked, "legacy_skipped": legacy}),
        )),
        Err(bad_id) => Ok(Json(json!({"ok": false, "bad_id": bad_id}))),
    }
}

