// ---------- approval slice: post-approval amendment ----------
// Post-approval amendment (F-D09-026): an approved request spawns a fresh
// pending request carrying the same entity + steps, so amended terms go
// through full re-approval instead of editing a closed record.
#[derive(Debug, Deserialize)]
struct AmendReq {
    title: Option<String>,
}
async fn appr_amend(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
    Json(b): Json<AmendReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    let (req, steps) = s
        .stores
        .ops
        .appr_get(&u.claims.org, id)
        .await
        .map_err(map_store)?;
    if req.status != "approved" {
        return Err(AppError::Conflict("only approved may be amended".into()));
    }
    let title = b
        .title
        .map(|t| t.trim().to_string())
        .filter(|t| !t.is_empty());
    let title = title.unwrap_or_else(|| format!("Amendemen #{}: {}", id, req.title));
    if title.len() > 200 {
        return Err(AppError::Validation("title".into()));
    }
    let roster: Vec<(i64, String)> = steps.iter().map(|x| (x.step_no, x.role.clone())).collect();
    let nid = s
        .stores
        .ops
        .appr_create(
            &u.claims.org,
            &req.entity,
            req.entity_id,
            &title,
            &u.claims.sub,
            &roster,
        )
        .await
        .map_err(map_store)?;
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: "approval.amended".into(),
            entity: "approval".into(),
            entity_id: nid,
            ip: None,
        },
    )
    .await;
    Ok(Json(json!({"id": nid, "amends": id, "title": title})))
}
// ---------- end approval slice: amendment ----------

// ---------- approval slice: amount + risk routing ----------
// Routing engine (F-D09-012/013): ordered roles for (entity, entity_id).
// Amount = invoice total, or open-AR sum for matter/deed matters (deed
// resolves through its matter; unknown amounts count as 0). Risk = the
// shared AML score of the matter's client (matters without clients score
// the individual baseline).
#[derive(Debug, Deserialize, Validate)]
struct RouteRuleReq {
    #[validate(length(min = 1, max = 10))]
    kind: String,
    #[validate(length(min = 1, max = 20))]
    entity: String,
    min_value: Option<i64>,
    #[validate(length(min = 2, max = 60))]
    role: String,
    priority: Option<i64>,
    #[validate(length(max = 500))]
    note: Option<String>,
}
async fn aroute_add(
    State(s): State<FullState>,
    headers: HeaderMap,
    Json(b): Json<RouteRuleReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    require_admin(&u)?;
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    let id = s
        .stores
        .ops
        .aroute_add(
            &u.claims.org,
            b.kind.trim(),
            b.entity.trim(),
            b.min_value.unwrap_or(0),
            b.role.trim(),
            b.priority.unwrap_or(0),
            b.note.as_deref().unwrap_or(""),
        )
        .await
        .map_err(map_store)?;
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: "approval.route_saved".into(),
            entity: "aroute".into(),
            entity_id: id,
            ip: None,
        },
    )
    .await;
    Ok(Json(json!({"id": id})))
}
