// ---------- document slice: bundle + OCR auto-queue ----------
// Bulk download (F-D04-011): one JSON bundle with base64 contents, capped at
// 25 MiB of raw bytes so a giant matter cannot OOM the server (413).
async fn doc_bundle(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(mid): Path<i64>,
) -> Result<Json<Value>, AppError> {
    use base64::Engine as _;
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Download)?;
    visible_matter(&s, &u, mid).await?;
    let docs = s
        .stores
        .core
        .list_docs(&u.claims.org, Some(mid))
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    const CAP: u64 = 25 * 1024 * 1024;
    let total: u64 = docs.iter().map(|d| d.size).sum();
    if total > CAP {
        return Err(AppError::Validation("bundle too large".into()));
    }
    let mut files = Vec::new();
    for d in docs {
        let (_, vs) = s
            .stores
            .core
            .get_doc(&u.claims.org, d.id)
            .await
            .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
        let latest = vs
            .last()
            .ok_or_else(|| AppError::NotFound("content".into()))?;
        let bytes = s.stores.objects.get(&latest.object_key).await?;
        files.push(
            json!({"id": d.id, "name": d.name, "mime": d.mime, "size": d.size,
            "content_base64": base64::engine::general_purpose::STANDARD.encode(&bytes)}),
        );
    }
    Ok(Json(
        json!({"matter_id": mid, "files": files.len(), "bytes": total, "entries": files}),
    ))
}
// ---------- end document slice: bundle ----------

// ---------- document slice: chunked upload (F-D09-035) ----------
// Resumable intake (F-D04-035): open a session, PUT chunks in order, then
// complete into a real document + first version. Sessions are ephemeral
// (documented: a restart drops them); ownership is per-creator.
#[derive(Debug, Deserialize, Validate)]
struct UpStartReq {
    #[validate(length(min = 1, max = 255))]
    name: String,
    #[validate(length(min = 1, max = 120))]
    mime: String,
    size: u64,
    #[validate(length(min = 64, max = 64))]
    sha: String,
}
async fn up_start(
    State(s): State<FullState>,
    headers: HeaderMap,
    Json(b): Json<UpStartReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    legalrust_document::validate_upload(&b.mime, b.size, MAX_UPLOAD)
        .map_err(|e| AppError::Validation(e.to_string()))?;
    quota_check(&s, &u.claims.org, b.size).await?;
    let id = s
        .stores
        .ops
        .up_start(
            &u.claims.org,
            &u.claims.sub,
            b.name.trim(),
            b.mime.trim(),
            b.size,
            b.sha.trim(),
        )
        .await
        .map_err(map_store)?;
    Ok(Json(json!({"id": id, "received": 0})))
}
async fn up_chunk(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
    body: axum::body::Bytes,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    let received = s
        .stores
        .ops
        .up_append(&u.claims.org, &u.claims.sub, id, &body)
        .await
        .map_err(map_store)?;
    Ok(Json(json!({"id": id, "received": received})))
}
async fn up_complete(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    let (name, mime, size, sha, bytes) = s
        .stores
        .ops
        .up_take(&u.claims.org, &u.claims.sub, id)
        .await
        .map_err(map_store)?;
    let actual = legalrust_document::sha256_hex(&bytes);
    if actual != sha {
        return Err(AppError::Validation("sha256 mismatch".into()));
    }
    let doc = s
        .stores
        .core
        .create_doc(&u.claims.org, None, &name, &mime, size, &sha)
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    let key = format!("docs/{}/content", doc.id);
    s.stores.objects.put(&key, &bytes).await?;
    let v = s
        .stores
        .core
        .add_version(&u.claims.org, doc.id, &key, &sha)
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    // Text uploads join the search index immediately (same rule as PUT).
    if mime.starts_with("text/") {
        if let Ok(text) = String::from_utf8(bytes) {
            let chunks = legalrust_rag::chunk_text(&text, 800, 100);
            let _ = s.stores.ops.rag_put(doc.id, &chunks).await;
        }
    }
    if mime.starts_with("image/") {
        let _ = s
            .stores
            .ops
            .ocr_create(&u.claims.org, doc.id, "general")
            .await;
    }
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: "document.upload_completed".into(),
            entity: "document".into(),
            entity_id: doc.id,
            ip: None,
        },
    )
    .await;
    Ok(Json(
        json!({"doc_id": doc.id, "version": v.version_no, "size": size}),
    ))
}
async fn up_abort(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    s.stores
        .ops
        .up_abort(&u.claims.org, &u.claims.sub, id)
        .await
        .map_err(map_store)?;
    Ok(Json(json!({"aborted": true})))
}
