async fn client_ltv(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(cid): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    if !client_exists(&s, &u.claims.org, cid).await? {
        return Err(AppError::NotFound("client".into()));
    }
    let matters = visible_matters(&s, &u).await?;
    let mine: Vec<i64> = matters
        .iter()
        .filter(|m| m.client_id == Some(cid))
        .map(|m| m.id)
        .collect();
    let open = s
        .stores
        .ops
        .inv_list_open(&u.claims.org)
        .await
        .map_err(map_store)?;
    let mut invoiced = 0i64;
    for mid in &mine {
        let invs = s
            .stores
            .ops
            .inv_list(&u.claims.org, *mid)
            .await
            .map_err(map_store)?;
        invoiced += invs.iter().map(|r| r.total).sum::<i64>();
    }
    let open_minor: i64 = open
        .iter()
        .filter(|r| mine.contains(&r.matter_id))
        .map(|r| r.balance)
        .sum();
    Ok(Json(
        json!({"client_id": cid, "matters": mine.len() as i64, "invoiced_minor": invoiced,
        "open_minor": open_minor, "paid_minor": invoiced - open_minor}),
    ))
}
