// ---------- client slice: merge + corrections ----------
// Data merge & dedupe (F-D02-025): keep/drop merge. Ops-side rows move in
// one Tx (mysql) / one lock (memory); matters move via CoreStore; the drop
// client deletes only when nothing references it. Each leg is atomic and
// retry-safe; a mid-flow failure leaves consistent, re-runnable state.
#[derive(Debug, Deserialize, Validate)]
struct CmergeReq {
    keep_id: i64,
    drop_id: i64,
}
async fn cmerge_execute(
    State(s): State<FullState>,
    headers: HeaderMap,
    Json(b): Json<CmergeReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Delete)?;
    require_admin(&u)?;
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    if b.keep_id == b.drop_id {
        return Err(AppError::Validation("keep_id".into()));
    }
    for cid in [b.keep_id, b.drop_id] {
        if !client_exists(&s, &u.claims.org, cid).await? {
            return Err(AppError::NotFound("client".into()));
        }
    }
    s.stores
        .ops
        .cmerge_execute(&u.claims.org, b.keep_id, b.drop_id)
        .await
        .map_err(map_store)?;
    let moved = s
        .stores
        .core
        .repoint_matters(&u.claims.org, b.drop_id, b.keep_id)
        .await
        .map_err(map_store)?;
    s.stores
        .core
        .delete_client_if_empty(&u.claims.org, b.drop_id)
        .await
        .map_err(map_store)?;
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: "client.merged".into(),
            entity: "client".into(),
            entity_id: b.keep_id,
            ip: None,
        },
    )
    .await;
    Ok(Json(json!({"keep_id": b.keep_id, "merged_matters": moved})))
}
// Data correction requests (F-D02-026): request -> approve/reject (SoD)
// -> apply writes the field through CoreStore, then marks applied.
#[derive(Debug, Deserialize, Validate)]
struct CcorReq {
    client_id: i64,
    #[validate(length(min = 1, max = 20))]
    field: String,
    #[validate(length(max = 255))]
    old_value: Option<String>,
    #[validate(length(min = 1, max = 255))]
    new_value: String,
}
async fn ccor_add(
    State(s): State<FullState>,
    headers: HeaderMap,
    Json(b): Json<CcorReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    if !client_exists(&s, &u.claims.org, b.client_id).await? {
        return Err(AppError::NotFound("client".into()));
    }
    let id = s
        .stores
        .ops
        .ccor_add(
            &u.claims.org,
            b.client_id,
            b.field.trim(),
            b.old_value.as_deref().unwrap_or(""),
            b.new_value.trim(),
            &u.claims.sub,
        )
        .await
        .map_err(map_store)?;
    Ok(Json(json!({"id": id, "status": "requested"})))
}
#[derive(Debug, Deserialize)]
struct CcorQ {
    client_id: Option<i64>,
}
