async fn cnr_resolve(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(cid): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    if !client_exists(&s, &u.claims.org, cid).await? {
        return Err(AppError::NotFound("client".into()));
    }
    let emps = s
        .stores
        .ops
        .cemp_list(&u.claims.org, cid)
        .await
        .map_err(map_store)?;
    let routes = s
        .stores
        .ops
        .cnr_list(&u.claims.org, Some(cid))
        .await
        .map_err(map_store)?;
    let consents = s
        .stores
        .ops
        .ccns_list(&u.claims.org, cid)
        .await
        .map_err(map_store)?;
    let allowed: std::collections::HashMap<String, bool> = consents
        .into_iter()
        .map(|r| (r.channel, r.allowed))
        .collect();
    let mut plan: Vec<Value> = Vec::new();
    for r in routes {
        let ok = allowed.get(&r.channel).copied().unwrap_or(true);
        plan.push(json!({"to": r.name, "channel": r.channel, "target": r.target, "allowed": ok}));
    }
    for e in emps {
        if !e.contact.is_empty() {
            plan.push(
                json!({"to": e.name, "channel": "employee", "target": e.contact, "allowed": true}),
            );
        }
    }
    Ok(Json(json!({"client_id": cid, "routes": plan})))
}
async fn clients_csv_export(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<impl IntoResponse, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Export)?;
    let v = s
        .stores
        .core
        .list_clients(&u.claims.org)
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    let mut csv = String::from("id,display_name,kind,status\n");
    for c in &v {
        csv.push_str(&format!(
            "{},{},{},{}\n",
            c.id,
            csv_field(&c.display_name),
            csv_field(&c.kind),
            csv_field(&c.status)
        ));
    }
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: "report.clients_csv_exported".into(),
            entity: "report".into(),
            entity_id: 0,
            ip: None,
        },
    )
    .await;
    let mut h = HeaderMap::new();
    h.insert(
        "content-type",
        HeaderValue::from_static("text/csv; charset=utf-8"),
    );
    Ok((StatusCode::OK, h, csv))
}
