// ---------- end portal slice: invoices + booking ----------

// ---------- portal slice: case messages + portal audit ----------
// Case-message thread (F-D19-013): client<->staff messages scoped to a
// client (optional matter). Clients post as themselves; staff read and
// reply from the client panel. Portal audit trail (F-D19-031): the
// portal-scoped view of the shared audit log (own client rows only).
#[derive(Debug, Deserialize, Validate)]
struct CmsgReq {
    client_id: i64,
    matter_id: Option<i64>,
    #[validate(length(min = 2, max = 2000))]
    body: String,
}
async fn cmsg_staff_add(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(cid): Path<i64>,
    Json(b): Json<CmsgReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    if b.client_id != cid || !client_exists(&s, &u.claims.org, cid).await? {
        return Err(AppError::NotFound("client".into()));
    }
    if let Some(mid) = b.matter_id {
        let m = s
            .stores
            .core
            .get_matter(&u.claims.org, mid)
            .await
            .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
        if m.client_id != Some(b.client_id) {
            return Err(AppError::Validation("matter_id".into()));
        }
    }
    let id = s
        .stores
        .ops
        .cmsg_add(
            &u.claims.org,
            b.client_id,
            b.matter_id,
            "staff",
            b.body.trim(),
        )
        .await
        .map_err(map_store)?;
    Ok(Json(json!({"id": id})))
}
#[derive(Debug, Deserialize)]
struct CmsgQ {
    matter_id: Option<i64>,
}
