#[derive(Debug, Deserialize)]
struct PortalApptQ {
    upcoming_days: Option<i64>,
}
async fn portal_appt_reminders(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<PortalApptQ>,
) -> Result<Json<Value>, AppError> {
    let (org, cid) = portal_client(&headers, &s).await?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let clients = s.stores.core.list_clients(&org).await.map_err(map_e)?;
    let name = clients
        .iter()
        .find(|c| c.id == cid)
        .map(|c| c.display_name.clone())
        .unwrap_or_default();
    let days = q.upcoming_days.unwrap_or(7).clamp(1, 90);
    let horizon = (chrono::Utc::now().naive_utc().date() + chrono::Duration::days(days))
        .format("%Y-%m-%d")
        .to_string();
    let today = chrono::Utc::now()
        .naive_utc()
        .date()
        .format("%Y-%m-%d")
        .to_string();
    let v = s.stores.ops.appt_list(&org).await.map_err(map_store)?;
    Ok(Json(json!(v
        .iter()
        .filter(|a| a.client_name == name
            && a.status == "scheduled"
            && a.scheduled_at.as_str() >= today.as_str()
            && a.scheduled_at.as_str() <= format!("{horizon} 23:59").as_str())
        .map(|a| json!({"id": a.id, "purpose": a.purpose, "scheduled_at": a.scheduled_at, "status": a.status}))
        .collect::<Vec<_>>())))
}
// ---------- end portal slice: announcements + reminders ----------

// ---------- portal slice: downloads + quote requests ----------
// Download center (F-D19-025): the client's own documents with version
// counts and download URLs (same ownership guard as the content route).
// Quotation requests (F-D19-017): portal intake that lands in the staff
// marketing-lead pipeline (source=portal) for follow-up and pricing.
async fn portal_downloads(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let (org, cid) = portal_client(&headers, &s).await?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let matters = s.stores.core.list_matters(&org).await.map_err(map_e)?;
    let mut out = Vec::new();
    for m in matters.iter().filter(|m| m.client_id == Some(cid)) {
        let docs = s
            .stores
            .core
            .list_docs(&org, Some(m.id))
            .await
            .map_err(map_e)?;
        for d in &docs {
            let (_, vs) = s.stores.core.get_doc(&org, d.id).await.map_err(map_e)?;
            if vs.is_empty() {
                continue;
            }
            out.push(
                json!({"id": d.id, "matter_id": m.id, "matter_title": m.title,
                "name": d.name, "mime": d.mime, "versions": vs.len() as i64,
                "url": format!("/api/v1/documents/{}/content", d.id)}),
            );
        }
    }
    Ok(Json(json!(out)))
}
