// ---------- reports slice: KPI dashboards (F-D20-007/008/015) ----------
// Firm-wide KPI rollups over existing tables (no new storage):
// matter KPIs, financial KPIs (invoices + trust), staff utilization.
async fn kpi_matters(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let matters = visible_matters(&s, &u).await?;
    let mut by_status = std::collections::HashMap::new();
    let mut by_priority = std::collections::HashMap::new();
    let mut open_tasks: i64 = 0;
    let mut overdue_tasks: i64 = 0;
    let mut teamless: i64 = 0;
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    for m in &matters {
        *by_status.entry(m.status.clone()).or_insert(0i64) += 1;
        *by_priority.entry(m.priority.clone()).or_insert(0i64) += 1;
        let team = s
            .stores
            .ops
            .mteam_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        if team.is_empty() {
            teamless += 1;
        }
        let tasks = s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_e)?;
        for t in &tasks {
            if t.status == "done" {
                continue;
            }
            open_tasks += 1;
            if t.due.as_deref().is_some_and(|d| d < now.as_str()) {
                overdue_tasks += 1;
            }
        }
    }
    Ok(Json(json!({
        "matters_total": matters.len() as i64,
        "by_status": by_status, "by_priority": by_priority,
        "open_tasks": open_tasks, "overdue_tasks": overdue_tasks,
        "matters_without_team": teamless,
    })))
}
async fn kpi_finance(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let matters = visible_matters(&s, &u).await?;
    let mut billed: i64 = 0;
    let mut collected: i64 = 0;
    let mut open_invoices: i64 = 0;
    for m in &matters {
        let inv = s
            .stores
            .ops
            .inv_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        for i in &inv {
            billed += i.total;
            let paid: i64 = s
                .stores
                .ops
                .inv_get(&u.claims.org, i.id)
                .await
                .map_err(map_store)
                .map(|(_, ps)| ps.iter().map(|p| p.amount).sum())
                .unwrap_or(0);
            collected += paid;
            if paid < i.total {
                open_invoices += 1;
            }
        }
    }
    let trusts = s
        .stores
        .ops
        .trust_list(&u.claims.org)
        .await
        .map_err(map_store)?;
    let trust_balance: i64 = trusts.iter().map(|a| a.balance).sum();
    Ok(Json(json!({
        "billed": billed, "collected": collected,
        "outstanding": billed - collected, "open_invoices": open_invoices,
        "trust_accounts": trusts.len() as i64, "trust_balance": trust_balance,
    })))
}
async fn kpi_staff(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let entries = s
        .stores
        .ops
        .ten_list(&u.claims.org, None, None)
        .await
        .map_err(map_store)?;
    let board = s
        .stores
        .core
        .task_board(&u.claims.org, 2000)
        .await
        .map_err(map_e)?;
    let mut users = std::collections::HashMap::new();
    for e in &entries {
        let r = users
            .entry(e.user_id.clone())
            .or_insert(json!({"user": e.user_id, "minutes": 0, "open_tasks": 0}));
        r["minutes"] = json!(r["minutes"].as_i64().unwrap_or(0) + e.minutes);
    }
    for t in &board {
        if t.status == "done" || t.assignee.trim().is_empty() {
            continue;
        }
        let r = users
            .entry(t.assignee.clone())
            .or_insert(json!({"user": t.assignee, "minutes": 0, "open_tasks": 0}));
        r["open_tasks"] = json!(r["open_tasks"].as_i64().unwrap_or(0) + 1);
    }
    let mut rows: Vec<serde_json::Value> = users.into_values().collect();
    rows.sort_by(|a, b| b["minutes"].as_i64().cmp(&a["minutes"].as_i64()));
    Ok(Json(json!(rows)))
}
// ---------- end reports slice: KPI dashboards ----------

// ---------- reports slice: exec reporting (F-D20-010/011/014) ----------
// JSON twins of CSV executive reports + AI usage/quality rollup.
// OCR sampling mirrors the CSV exporter (processed jobs only, mean of confidences).
async fn kpi_ocr(State(s): State<FullState>, headers: HeaderMap) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let jobs = s
        .stores
        .ops
        .ocr_list(&u.claims.org)
        .await
        .map_err(map_store)?;
    let mut samples: Vec<(String, i64, f32)> = Vec::new();
    let mut processed: i64 = 0;
    for j in &jobs {
        if j.status != "processed" {
            continue;
        }
        processed += 1;
        let (_, fields) = s
            .stores
            .ops
            .ocr_get(&u.claims.org, j.id)
            .await
            .map_err(map_store)?;
        if fields.is_empty() {
            continue;
        }
        let mean = fields.iter().map(|f| f.confidence as f64).sum::<f64>() / fields.len() as f64;
        samples.push((j.doc_type.clone(), fields.len() as i64, mean as f32));
    }
    let rows = legalrust_reporting::ocr_accuracy_aggregate(&samples);
    let overall = if rows.is_empty() {
        0.0
    } else {
        rows.iter().map(|r| r.avg_confidence as f64).sum::<f64>() / rows.len() as f64
    };
    Ok(Json(json!({
        "jobs_total": jobs.len() as i64, "jobs_processed": processed,
        "overall_confidence": overall,
        "by_type": rows.iter().map(|r| json!({
            "doc_type": r.doc_type, "jobs": r.jobs,
            "fields": r.fields, "avg_confidence": r.avg_confidence,
        })).collect::<Vec<_>>(),
    })))
}
async fn kpi_ai(State(s): State<FullState>, headers: HeaderMap) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let (convs, user_msgs, asst_msgs) = s
        .stores
        .ops
        .ai_stats(&u.claims.org)
        .await
        .map_err(map_store)?;
    let (input_tokens, output_tokens) = s
        .stores
        .ops
        .usage_sum(&u.claims.org)
        .await
        .map_err(map_store)?;
    Ok(Json(json!({
        "conversations": convs,
        "user_messages": user_msgs, "assistant_messages": asst_msgs,
        "reply_rate": if user_msgs > 0 { asst_msgs as f64 / user_msgs as f64 } else { 0.0 },
        "input_tokens": input_tokens, "output_tokens": output_tokens,
        "total_tokens": input_tokens + output_tokens,
    })))
}
async fn kpi_clients(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let clients = s
        .stores
        .core
        .list_clients(&u.claims.org)
        .await
        .map_err(map_e)?;
    let matters = visible_matters(&s, &u).await?;
    let open = s
        .stores
        .ops
        .inv_list_open(&u.claims.org)
        .await
        .map_err(map_store)?;
    let mut rows = Vec::new();
    for c in &clients {
        let mids: Vec<i64> = matters
            .iter()
            .filter(|m| m.client_id == Some(c.id))
            .map(|m| m.id)
            .collect();
        let mut billed: i64 = 0;
        let mut collected: i64 = 0;
        for mid in &mids {
            for i in s
                .stores
                .ops
                .inv_list(&u.claims.org, *mid)
                .await
                .map_err(map_store)?
            {
                billed += i.total;
                if let Some(r) = open.iter().find(|r| r.id == i.id) {
                    collected += r.paid;
                } else {
                    collected += i.total;
                }
            }
        }
        let outstanding: i64 = open
            .iter()
            .filter(|r| mids.contains(&r.matter_id))
            .map(|r| r.balance)
            .sum();
        rows.push(json!({"client_id": c.id, "client": c.display_name,
                         "matters": mids.len() as i64, "billed": billed,
                         "collected": collected, "outstanding": outstanding}));
    }
    rows.sort_by(|a, b| b["outstanding"].as_i64().cmp(&a["outstanding"].as_i64()));
    Ok(Json(json!(rows)))
}
async fn kpi_pack(State(s): State<FullState>, headers: HeaderMap) -> Result<Json<Value>, AppError> {
    // Executive summary pack: one payload bundling executive numbers,
    // posture registers, finance, deadlines, bottlenecks, deliveries.
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let org = &u.claims.org;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let clients = s.stores.core.list_clients(org).await.map_err(map_e)?;
    let matters = visible_matters(&s, &u).await?;
    let deeds = s.stores.ops.deed_list(org).await.map_err(map_store)?;
    let open_inv = s.stores.ops.inv_list_open(org).await.map_err(map_store)?;
    let open_bal: i64 = open_inv.iter().map(|r| r.balance).sum();
    let pending_appr = s
        .stores
        .ops
        .appr_list(org, Some("pending"))
        .await
        .map_err(map_store)?;
    let due = s
        .stores
        .core
        .task_due_list(org, 1000)
        .await
        .map_err(map_e)?;
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let overdue = due
        .iter()
        .filter(|t| t.status != "done" && t.due.as_deref().is_some_and(|d| d < now.as_str()))
        .count();
    let trusts = s.stores.ops.trust_list(org).await.map_err(map_store)?;
    let deliveries = s
        .stores
        .ops
        .webhook_list(org, None)
        .await
        .map_err(map_store)?;
    let failed_dl = deliveries
        .iter()
        .filter(|r| r.status != "accepted" && r.status != "delivered" && r.status != "sent")
        .count();
    let posture = posture_rows(&s, org).await?;
    Ok(Json(json!({
        "generated_at": chrono::Utc::now().naive_utc().format("%Y-%m-%d %H:%M:%S").to_string(),
        "executive": {"clients": clients.len(), "matters": matters.len(), "deeds": deeds.len(),
                      "open_invoices": open_inv.len(), "open_balance": open_bal,
                      "pending_approvals": pending_appr.len(), "tasks_due_tracked": due.len(),
                      "tasks_overdue": overdue},
        "posture": posture,
        "finance": {"outstanding": open_bal,
                    "trust_balance": trusts.iter().map(|a| a.balance).sum::<i64>()},
        "deadlines": {"tracked": due.len(), "overdue": overdue},
        "bottlenecks": {"pending": pending_appr.len()},
        "deliveries": {"total": deliveries.len(), "failed": failed_dl},
    })))
}
// ---------- end reports slice: exec reporting ----------

// ---------- reports slice: KPI alert thresholds (F-D20-030) ----------
// Stored thresholds (metric + op + value) evaluated live against current KPIs.
