async fn kpi_current_values(
    s: &FullState,
    u: &AuthUser,
) -> Result<std::collections::HashMap<String, i64>, AppError> {
    let matters = visible_matters(s, u).await?;
    let mut overdue_tasks: i64 = 0;
    let mut unassigned_tasks: i64 = 0;
    let mut matters_without_team: i64 = 0;
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    for m in &matters {
        if s.stores
            .ops
            .mteam_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?
            .is_empty()
        {
            matters_without_team += 1;
        }
        for t in s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_store)?
        {
            if t.status == "done" {
                continue;
            }
            if t.assignee.trim().is_empty() {
                unassigned_tasks += 1;
            }
            if t.due.as_deref().is_some_and(|d| d < now.as_str()) {
                overdue_tasks += 1;
            }
        }
    }
    let open = s
        .stores
        .ops
        .inv_list_open(&u.claims.org)
        .await
        .map_err(map_store)?;
    let outstanding: i64 = open.iter().map(|r| r.balance).sum();
    let trusts = s
        .stores
        .ops
        .trust_list(&u.claims.org)
        .await
        .map_err(map_store)?;
    let trust_balance: i64 = trusts.iter().map(|a| a.balance).sum();
    let pending = s
        .stores
        .ops
        .appr_list(&u.claims.org, Some("pending"))
        .await
        .map_err(map_store)?;
    Ok([
        ("overdue_tasks".into(), overdue_tasks),
        ("unassigned_tasks".into(), unassigned_tasks),
        ("matters_without_team".into(), matters_without_team),
        ("outstanding".into(), outstanding),
        ("trust_balance".into(), trust_balance),
        ("pending_approvals".into(), pending.len() as i64),
    ]
    .into_iter()
    .collect())
}
async fn kpi_alerts(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let rules = s
        .stores
        .ops
        .kth_list(&u.claims.org)
        .await
        .map_err(map_store)?;
    let current = kpi_current_values(&s, &u).await?;
    let mut breached = Vec::new();
    for r in &rules {
        if !r.active {
            continue;
        }
        if let Some(v) = current.get(&r.metric) {
            let hit = if r.op == ">=" {
                *v >= r.threshold
            } else {
                *v <= r.threshold
            };
            if hit {
                breached.push(json!({"metric": r.metric, "op": r.op,
                                     "threshold": r.threshold, "value": v}));
            }
        }
    }
    Ok(Json(
        json!({"breached": breached.len() as i64, "items": breached,
                   "evaluated": current}),
    ))
}

// ---------- reports slice: flow & delivery KPIs (F-D20-012/013/028) ----------
// JSON twins of the CSV flow reports + webhook delivery digest. Read-only.
fn age_days(created: &str, today: &str) -> i64 {
    if created.len() < 10 || today.len() < 10 {
        return 0;
    }
    let (d1, d2) = (&created[..10], &today[..10]);
    if d1 >= d2 {
        return 0;
    }
    // Bounded ordinal approximation (leap-safe enough for aging buckets).
    let ord = |d: &str| {
        let y: i64 = d[0..4].parse().unwrap_or(0);
        let m: i64 = d[5..7].parse().unwrap_or(0);
        let dd: i64 = d[8..10].parse().unwrap_or(0);
        y * 365 + y / 4 - y / 100 + y / 400 + m * 30 + dd
    };
    (ord(d2) - ord(d1)).max(0)
}
async fn kpi_bottlenecks(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let today = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d")
        .to_string();
    let pending = s
        .stores
        .ops
        .appr_list(&u.claims.org, Some("pending"))
        .await
        .map_err(map_store)?;
    let mut rows = Vec::new();
    for r in &pending {
        let (_, steps) = s
            .stores
            .ops
            .appr_get(&u.claims.org, r.id)
            .await
            .map_err(map_store)?;
        let stuck = steps
            .iter()
            .filter(|x| x.status == "pending")
            .min_by_key(|x| x.step_no);
        let open = steps.iter().filter(|x| x.status == "pending").count() as i64;
        rows.push(json!({
            "id": r.id, "title": r.title, "entity": r.entity,
            "stuck_step": stuck.map(|x| x.step_no).unwrap_or(-1),
            "stuck_role": stuck.map(|x| x.role.clone()).unwrap_or_else(|| "-".into()),
            "open_steps": open, "age_days": age_days(&r.created, &today),
        }));
    }
    rows.sort_by(|a, b| b["age_days"].as_i64().cmp(&a["age_days"].as_i64()));
    Ok(Json(json!({"pending": rows.len() as i64, "rows": rows})))
}
async fn kpi_deadlines(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<SlaAlertsQ>,
) -> Result<Json<Value>, AppError> {
    // Compliance view (done items excluded from overdue math, like the CSV):
    // per-matter totals + done + overdue + compliance %, plus org rollup.
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let window = q.days.unwrap_or(7).clamp(1, 90);
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let today = now[..10].to_string();
    let horizon = add_days(&today, window);
    let matters = visible_matters(&s, &u).await?;
    let mut rows = Vec::new();
    let (mut t_total, mut t_done, mut t_overdue, mut t_soon) = (0i64, 0i64, 0i64, 0i64);
    for m in &matters {
        let (mut total, mut done, mut overdue, mut soon) = (0i64, 0i64, 0i64, 0i64);
        for t in s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_e)?
        {
            if t.due.is_none() {
                continue;
            }
            total += 1;
            if t.status == "done" {
                done += 1;
                continue;
            }
            let d = t.due.as_deref().unwrap_or("");
            if d < now.as_str() {
                overdue += 1;
            } else if d.get(..10.min(d.len())) <= Some(horizon.as_str()) {
                soon += 1;
            }
        }
        for x in s
            .stores
            .ops
            .mms_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?
        {
            total += 1;
            if x.done {
                done += 1;
                continue;
            }
            if x.due_on < today {
                overdue += 1;
            } else if x.due_on <= horizon {
                soon += 1;
            }
        }
        if total == 0 {
            continue;
        }
        t_total += total;
        t_done += done;
        t_overdue += overdue;
        t_soon += soon;
        rows.push(json!({"matter_id": m.id, "matter": m.title, "total": total,
                         "done": done, "overdue": overdue, "due_soon": soon,
                         "compliance_pct": if total > 0 { (done * 100 / total) as f64 } else { 100.0 }}));
    }
    rows.sort_by(|a, b| {
        a["compliance_pct"]
            .as_f64()
            .partial_cmp(&b["compliance_pct"].as_f64())
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    Ok(Json(
        json!({"window_days": window, "matters": rows.len() as i64,
                   "total": t_total, "done": t_done, "overdue": t_overdue, "due_soon": t_soon,
                   "rows": rows}),
    ))
}
async fn kpi_deliveries(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let all = s
        .stores
        .ops
        .webhook_list(&u.claims.org, None)
        .await
        .map_err(map_store)?;
    let mut by_status = std::collections::HashMap::new();
    let mut by_provider = std::collections::HashMap::new();
    for r in &all {
        *by_status.entry(r.status.clone()).or_insert(0i64) += 1;
        *by_provider.entry(r.provider.clone()).or_insert(0i64) += 1;
    }
    let failed: Vec<serde_json::Value> = all
        .iter()
        .filter(|r| r.status != "accepted" && r.status != "delivered" && r.status != "sent")
        .take(20)
        .map(|r| {
            json!({"id": r.id, "provider": r.provider, "event": r.event,
                        "status": r.status, "direction": r.direction, "detail": r.detail})
        })
        .collect();
    Ok(Json(
        json!({"total": all.len() as i64, "by_status": by_status,
                   "by_provider": by_provider, "recent_failed": failed}),
    ))
}
