// Role-tailored KPI home, data-quality scorecard, metric dictionary. Read-only.
async fn kpi_home(State(s): State<FullState>, headers: HeaderMap) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let roles: Vec<String> = u.claims.roles.clone();
    let is = |r: &str| roles.iter().any(|x| x == r);
    let privileged = matter_privileged(&u);
    let mut sections: Vec<serde_json::Value> = Vec::new();
    macro_rules! sec {
        ($k:expr, $t:expr, $e:expr) => {
            sections.push(json!({"key": $k, "title": $t, "endpoint": $e}))
        };
    }
    if privileged || is("lawyer") || is("legal_staff") || is("notary") || is("ppat") {
        sec!("matters", "Perkara", "/api/v1/kpi/matters");
        sec!("pipeline", "Pipa status", "/api/v1/matters/pipeline");
        sec!("deadlines", "Kepatuhan tenggat", "/api/v1/kpi/deadlines");
        sec!("triage", "Triase inbox", "/api/v1/triage/queue");
        sec!("team", "Tim & beban", "/api/v1/kpi/staff");
    }
    if privileged || is("finance_officer") {
        sec!("finance", "Keuangan", "/api/v1/kpi/finance");
        sec!("clients", "Profitabilitas klien", "/api/v1/kpi/clients");
        sec!(
            "statement",
            "Statement (per perkara)",
            "/api/v1/matters/{id}/statement"
        );
    }
    if privileged || is("office_admin") {
        sec!("insights", "Wawasan", "/api/v1/matters/dashboard");
        sec!("deliveries", "Pengiriman", "/api/v1/kpi/deliveries");
        sec!("ocr", "Akurasi OCR", "/api/v1/kpi/ocr");
        sec!("ai", "AI", "/api/v1/kpi/ai");
    }
    if privileged || is("auditor") {
        sec!(
            "bottlenecks",
            "Kemacetan persetujuan",
            "/api/v1/kpi/bottlenecks"
        );
        sec!("audit", "Audit", "/api/v1/audit");
    }
    if sections.is_empty() {
        sec!("matters", "Perkara", "/api/v1/kpi/matters");
    }
    let _ = s;
    Ok(Json(json!({"roles": roles, "sections": sections})))
}
async fn kpi_quality(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let matters = visible_matters(&s, &u).await?;
    let total = matters.len() as i64;
    let with_client = matters.iter().filter(|m| m.client_id.is_some()).count() as i64;
    let mut with_team = 0i64;
    let mut with_budget = 0i64;
    let mut tasks_total = 0i64;
    let mut tasks_dated = 0i64;
    let mut tasks_assigned = 0i64;
    for m in &matters {
        if !s
            .stores
            .ops
            .mteam_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?
            .is_empty()
        {
            with_team += 1;
        }
        if !s
            .stores
            .ops
            .bdg_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?
            .is_empty()
        {
            with_budget += 1;
        }
        for t in s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_e)?
        {
            tasks_total += 1;
            if t.due.is_some() {
                tasks_dated += 1;
            }
            if !t.assignee.trim().is_empty() {
                tasks_assigned += 1;
            }
        }
    }
    let pct = |a: i64, b: i64| {
        if b == 0 {
            100.0
        } else {
            (a as f64) * 100.0 / (b as f64)
        }
    };
    Ok(Json(json!({
        "matters_total": total,
        "matters_with_client_pct": pct(with_client, total),
        "matters_with_team_pct": pct(with_team, total),
        "matters_with_budget_pct": pct(with_budget, total),
        "tasks_total": tasks_total,
        "tasks_dated_pct": pct(tasks_dated, tasks_total),
        "tasks_assigned_pct": pct(tasks_assigned, tasks_total),
    })))
}
