// ---------- matter slice: insights (F-D03-032/038/039) ----------
// Read-only firm-wide rollups over existing tables (no new storage):
// dashboard KPIs, per-matter profitability (budget vs actual + minutes),
// item-level SLA alerts (breached + due-soon window).
async fn matter_dashboard(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let matters = visible_matters(&s, &u).await?;
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let today = now[..10].to_string();
    let mut by_status = std::collections::HashMap::new();
    let mut by_priority = std::collections::HashMap::new();
    let mut tasks_open: i64 = 0;
    let mut tasks_overdue: i64 = 0;
    let mut miles_due_week: i64 = 0;
    for m in &matters {
        *by_status.entry(m.status.clone()).or_insert(0i64) += 1;
        *by_priority.entry(m.priority.clone()).or_insert(0i64) += 1;
        let tasks = s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_e)?;
        for t in &tasks {
            if t.status == "done" {
                continue;
            }
            tasks_open += 1;
            if t.due.as_deref().is_some_and(|d| d < now.as_str()) {
                tasks_overdue += 1;
            }
        }
        let mms = s
            .stores
            .ops
            .mms_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        miles_due_week += mms
            .iter()
            .filter(|x| !x.done && x.due_on >= today && x.due_on <= add_days(&today, 7))
            .count() as i64;
    }
    Ok(Json(json!({
        "matters_total": matters.len() as i64,
        "by_status": by_status,
        "by_priority": by_priority,
        "tasks_open": tasks_open,
        "tasks_overdue": tasks_overdue,
        "milestones_due_7d": miles_due_week,
    })))
}
fn add_days(day: &str, n: i64) -> String {
    // day is YYYY-MM-DD; naive +n days without chrono date math on strings.
    // Falls back to the input on malformed dates (caller treats empty range as none).
    let (y, m, d) = (
        day[0..4].parse::<i64>().unwrap_or(0),
        day[5..7].parse::<i64>().unwrap_or(0),
        day[8..10].parse::<i64>().unwrap_or(0),
    );
    if y < 2000 || !(1..=12).contains(&m) || !(1..=31).contains(&d) {
        return day.into();
    }
    let mut y = y;
    let mut m = m;
    let mut d = d + n;
    loop {
        let dim = match m {
            2 if y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) => 29,
            2 => 28,
            4 | 6 | 9 | 11 => 30,
            _ => 31,
        };
        if d <= dim {
            break;
        }
        d -= dim;
        m += 1;
        if m > 12 {
            m = 1;
            y += 1;
        }
    }
    format!("{y:04}-{m:02}-{d:02}")
}
async fn matter_profitability(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let matters = visible_matters(&s, &u).await?;
    let mut rows = Vec::new();
    for m in &matters {
        let b = s
            .stores
            .ops
            .bdg_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        let x = s
            .stores
            .ops
            .mxp_list(&u.claims.org, m.id, None)
            .await
            .map_err(map_store)?;
        let t = s
            .stores
            .ops
            .ten_list(&u.claims.org, Some(m.id), None)
            .await
            .map_err(map_store)?;
        let budget: i64 = b.iter().map(|r| r.amount).sum();
        let spent: i64 = x
            .iter()
            .filter(|r| r.kind == "expense")
            .map(|r| r.amount)
            .sum();
        let minutes: i64 = t.iter().map(|r| r.minutes).sum();
        rows.push(json!({
            "matter_id": m.id, "title": m.title, "status": m.status,
            "budget": budget, "spent": spent, "remaining": budget - spent,
            "minutes_logged": minutes,
        }));
    }
    rows.sort_by(|a, b| a["remaining"].as_i64().cmp(&b["remaining"].as_i64()));
    Ok(Json(json!(rows)))
}
#[derive(Debug, Deserialize)]
struct SlaAlertsQ {
    days: Option<i64>,
}
async fn matter_sla_alerts(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<SlaAlertsQ>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let window = q.days.unwrap_or(7).clamp(1, 90);
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let today = now[..10].to_string();
    let horizon = add_days(&today, window);
    let matters = visible_matters(&s, &u).await?;
    let mut items = Vec::new();
    for m in &matters {
        let tasks = s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_e)?;
        for t in &tasks {
            if t.status == "done" {
                continue;
            }
            if let Some(d) = t.due.as_deref() {
                let sev = if d < now.as_str() {
                    "breached"
                } else if d.get(..10.min(d.len())) <= Some(horizon.as_str()) {
                    "due_soon"
                } else {
                    continue;
                };
                items.push(json!({
                    "matter_id": m.id, "matter": m.title, "kind": "task",
                    "ref_id": t.id, "title": t.title, "due": &d[..10.min(d.len())], "severity": sev,
                }));
            }
        }
        let mms = s
            .stores
            .ops
            .mms_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        for x in &mms {
            if x.done {
                continue;
            }
            let sev = if x.due_on < today {
                "breached"
            } else if x.due_on <= horizon {
                "due_soon"
            } else {
                continue;
            };
            items.push(json!({
                "matter_id": m.id, "matter": m.title, "kind": "milestone",
                "ref_id": x.id, "title": x.title, "due": x.due_on, "severity": sev,
            }));
        }
    }
    items.sort_by(|a, b| a["due"].as_str().cmp(&b["due"].as_str()));
    Ok(Json(json!({"window_days": window, "items": items})))
}
// ---------- end matter slice: insights ----------

// ---------- matter slice: statement + bulk import (F-D03-033/036) ----------
// Per-matter client statement: invoices with paid/balance + totals.
// Bulk import: validate-all-then-create (no silent partials), capped 100 rows.
async fn matter_statement(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(mid): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let m = visible_matter(&s, &u, mid).await?;
    let inv = s
        .stores
        .ops
        .inv_list(&u.claims.org, mid)
        .await
        .map_err(map_store)?;
    let mut rows = Vec::new();
    let mut billed: i64 = 0;
    let mut paid_sum: i64 = 0;
    for i in &inv {
        let paid: i64 = s
            .stores
            .ops
            .inv_get(&u.claims.org, i.id)
            .await
            .map_err(map_store)
            .map(|(_, ps)| ps.iter().map(|p| p.amount).sum())
            .unwrap_or(0);
        billed += i.total;
        paid_sum += paid;
        rows.push(json!({"id": i.id, "number": i.number, "total": i.total,
                         "paid": paid, "balance": i.total - paid, "status": i.status}));
    }
    Ok(Json(json!({
        "matter": {"id": m.id, "title": m.title, "number": m.number, "status": m.status},
        "invoices": rows,
        "totals": {"billed": billed, "paid": paid_sum, "outstanding": billed - paid_sum},
    })))
}
async fn matter_statement_csv(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(mid): Path<i64>,
) -> Result<impl IntoResponse, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Export)?;
    visible_matter(&s, &u, mid).await?;
    let inv = s
        .stores
        .ops
        .inv_list(&u.claims.org, mid)
        .await
        .map_err(map_store)?;
    let mut csv = String::from("invoice_id,number,total,paid,balance,status\n");
    let mut billed: i64 = 0;
    let mut paid_sum: i64 = 0;
    for i in &inv {
        let paid: i64 = s
            .stores
            .ops
            .inv_get(&u.claims.org, i.id)
            .await
            .map_err(map_store)
            .map(|(_, ps)| ps.iter().map(|p| p.amount).sum())
            .unwrap_or(0);
        billed += i.total;
        paid_sum += paid;
        csv.push_str(&format!(
            "{},{},{},{},{},{}\n",
            i.id,
            i.number,
            i.total,
            paid,
            i.total - paid,
            i.status
        ));
    }
    csv.push_str(&format!(
        "TOTAL,,{billed},{paid_sum},{}\n",
        billed - paid_sum
    ));
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: "report.matter_statement_csv".into(),
            entity: "report".into(),
            entity_id: mid,
            ip: None,
        },
    )
    .await;
    let mut h = HeaderMap::new();
    h.insert(
        "content-type",
        HeaderValue::from_static("text/csv; charset=utf-8"),
    );
    Ok((StatusCode::OK, h, csv))
}
#[derive(Debug, Deserialize, Validate)]
struct MatterImportRow {
    #[validate(length(min = 2, max = 200))]
    title: String,
    client_id: Option<i64>,
}
#[derive(Debug, Deserialize, Validate)]
struct MatterImportReq {
    rows: Vec<MatterImportRow>,
}
async fn matter_import(
    State(s): State<FullState>,
    headers: HeaderMap,
    Json(b): Json<MatterImportReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    if b.rows.is_empty() || b.rows.len() > 100 {
        return Err(AppError::Validation("rows 1-100".into()));
    }
    for r in &b.rows {
        r.validate()
            .map_err(|e| AppError::Validation(e.to_string()))?;
    }
    // Validate-all-then-create: unknown clients rejected before any write.
    if b.rows.iter().any(|r| r.client_id.is_some()) {
        let map_e =
            |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
        let clients = s
            .stores
            .core
            .list_clients(&u.claims.org)
            .await
            .map_err(map_e)?;
        for r in &b.rows {
            if let Some(cid) = r.client_id {
                if !clients.iter().any(|c| c.id == cid) {
                    return Err(AppError::NotFound("client".into()));
                }
            }
        }
    }
    let mut ids = Vec::new();
    for r in &b.rows {
        let number = format!("M-{}", uuid::Uuid::new_v4().to_string()[..8].to_uppercase());
        let m: legalrust_database::MatterRow = s
            .stores
            .core
            .create_matter(&u.claims.org, r.client_id, &number, r.title.trim())
            .await
            .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
        audit(
            &s.pool,
            &s.stores,
            AuditEvent {
                tenant_id: u.claims.org.clone(),
                actor_id: Some(u.claims.sub.clone()),
                action: "matter.created".into(),
                entity: "matter".into(),
                entity_id: m.id,
                ip: None,
            },
        )
        .await;
        ids.push(json!({"id": m.id, "number": m.number}));
    }
    notify_user(
        &s,
        &u.claims.org,
        &u.claims.sub,
        "matter",
        &format!("Bulk import: {} matters", ids.len()),
    )
    .await;
    Ok(Json(json!({"created": ids.len() as i64, "matters": ids})))
}
// ---------- end matter slice: statement + import ----------

// ---------- matter slice: inbox triage (F-D03-040) ----------
// Read-only triage queue (unassigned work) + load-based assignee suggestion.
// Assignment itself reuses POST /api/v1/tasks/{tid}/assign.
async fn triage_queue(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let matters = visible_matters(&s, &u).await?;
    let mut items = Vec::new();
    for m in &matters {
        if m.status == "closed" {
            continue;
        }
        let team = s
            .stores
            .ops
            .mteam_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        if team.is_empty() {
            items.push(json!({"kind": "matter_no_team", "matter_id": m.id, "title": m.title}));
        }
        let tasks = s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_e)?;
        for t in &tasks {
            if t.status != "done" && t.assignee.trim().is_empty() && items.len() < 200 {
                items.push(json!({"kind": "task_unassigned", "task_id": t.id,
                                   "matter_id": m.id, "title": t.title, "due": t.due}));
            }
        }
        if items.len() >= 200 {
            break;
        }
    }
    Ok(Json(json!({"items": items})))
}
#[derive(Debug, Deserialize)]
struct TriageSuggestReq {
    task_id: i64,
}
async fn triage_suggest(
    State(s): State<FullState>,
    headers: HeaderMap,
    Json(b): Json<TriageSuggestReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let t = s
        .stores
        .core
        .task_get(&u.claims.org, b.task_id)
        .await
        .map_err(|_| AppError::NotFound("task".into()))?;
    if !t.assignee.trim().is_empty() {
        return Ok(Json(
            json!({"suggested": t.assignee, "reason": "already_assigned"}),
        ));
    }
    let team = s
        .stores
        .ops
        .mteam_list(&u.claims.org, t.matter_id)
        .await
        .map_err(map_store)?;
    let cands: Vec<String> = team
        .iter()
        .filter(|r| r.role == "lead" || r.role == "member")
        .map(|r| r.user_id.clone())
        .collect();
    if cands.is_empty() {
        return Ok(Json(
            json!({"suggested": serde_json::Value::Null, "reason": "no_team"}),
        ));
    }
    let all = s
        .stores
        .core
        .task_board(&u.claims.org, 2000)
        .await
        .map_err(map_e)?;
    let mut best: Option<(String, i64)> = None;
    for c in &cands {
        let load = all
            .iter()
            .filter(|x| x.status != "done" && &x.assignee == c)
            .count() as i64;
        if best.as_ref().map(|(_, l)| load < *l).unwrap_or(true) {
            best = Some((c.clone(), load));
        }
    }
    let (who, load) = best.expect("candidates non-empty");
    Ok(Json(
        json!({"suggested": who, "open_tasks": load, "reason": "least_open_tasks"}),
    ))
}
