// ---------- matter slice: deadline engine + calculator ----------
// Deadline & SLA engine (F-D03-008): per-matter and org-wide deadline
// rollups over tasks (due_at) and milestones (due_on), with overdue
// flags against server time. Court/agency calculator (F-D03-009):
// start-date + N days with optional weekend skipping, plus reference
// presets for common remedies (verify against current regulation —
// presets are convenience defaults, not legal advice).
async fn matter_deadlines(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(mid): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    visible_matter(&s, &u, mid).await?;
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let today = now[..10].to_string();
    let tasks = s
        .stores
        .core
        .list_tasks(&u.claims.org, mid)
        .await
        .map_err(map_e)?;
    let mut tt = Vec::new();
    for t in tasks.iter().filter(|t| t.status != "done") {
        let od = t.due.as_deref().is_some_and(|d| d < now.as_str());
        tt.push(
            json!({"id": t.id, "title": t.title, "due": t.due, "status": t.status, "overdue": od}),
        );
    }
    let mms = s
        .stores
        .ops
        .mms_list(&u.claims.org, mid)
        .await
        .map_err(map_store)?;
    let mut mm = Vec::new();
    for m in mms.iter().filter(|m| !m.done) {
        mm.push(
            json!({"id": m.id, "title": m.title, "due_on": m.due_on, "overdue": m.due_on < today}),
        );
    }
    let overdue = tt.iter().filter(|t| t["overdue"] == true).count() as i64
        + mm.iter().filter(|m| m["overdue"] == true).count() as i64;
    Ok(Json(
        json!({"matter_id": mid, "tasks": tt, "milestones": mm, "overdue": overdue, "breached": overdue > 0}),
    ))
}
async fn deadline_summary(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let matters = visible_matters(&s, &u).await?;
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let today = now[..10].to_string();
    let mut out = Vec::new();
    for m in &matters {
        let tasks = s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_e)?;
        let tod: i64 = tasks
            .iter()
            .filter(|t| t.status != "done" && t.due.as_deref().is_some_and(|d| d < now.as_str()))
            .count() as i64;
        let mms = s
            .stores
            .ops
            .mms_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        let mod_: i64 = mms.iter().filter(|x| !x.done && x.due_on < today).count() as i64;
        if tod + mod_ > 0 {
            out.push(json!({"matter_id": m.id, "title": m.title, "task_overdue": tod, "milestone_overdue": mod_}));
        }
    }
    Ok(Json(
        json!({"breached_matters": out.len() as i64, "rows": out}),
    ))
}
#[derive(Debug, Deserialize, Validate)]
struct DlCalcReq {
    #[validate(length(min = 10, max = 10))]
    start: String,
    days: Option<i64>,
    skip_weekends: Option<bool>,
}
async fn deadline_calc(Json(b): Json<DlCalcReq>) -> Result<Json<Value>, AppError> {
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    let days = b.days.unwrap_or(14).clamp(1, 3650);
    let start = chrono::NaiveDate::parse_from_str(b.start.trim(), "%Y-%m-%d")
        .map_err(|_| AppError::Validation("start YYYY-MM-DD".into()))?;
    let mut d = start;
    if b.skip_weekends.unwrap_or(false) {
        let mut left = days;
        while left > 0 {
            d = d.succ_opt().ok_or(AppError::Validation("date".into()))?;
            if !matches!(d.weekday(), chrono::Weekday::Sat | chrono::Weekday::Sun) {
                left -= 1;
            }
        }
    } else {
        d = start
            .checked_add_days(chrono::Days::new(days as u64))
            .ok_or(AppError::Validation("date".into()))?;
    }
    Ok(Json(
        json!({"start": start.format("%Y-%m-%d").to_string(), "days": days,
        "skip_weekends": b.skip_weekends.unwrap_or(false),
        "due": d.format("%Y-%m-%d").to_string(), "weekday": d.weekday().to_string(),
        "note": "reference math only — verify against current regulation"}),
    ))
}
