async fn cost_summary(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(mid): Path<i64>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    visible_matter(&s, &u, mid).await?;
    let b = s
        .stores
        .ops
        .bdg_list(&u.claims.org, mid)
        .await
        .map_err(map_store)?;
    let x = s
        .stores
        .ops
        .mxp_list(&u.claims.org, mid, None)
        .await
        .map_err(map_store)?;
    let budget: i64 = b.iter().map(|r| r.amount).sum();
    let spent: i64 = x
        .iter()
        .filter(|r| r.kind == "expense")
        .map(|r| r.amount)
        .sum();
    let advances: i64 = x
        .iter()
        .filter(|r| r.kind == "advance")
        .map(|r| r.amount)
        .sum();
    Ok(Json(json!({
        "matter_id": mid,
        "budget": budget,
        "spent": spent,
        "advances": advances,
        "remaining": budget - spent,
        "lines": b.iter().map(|r| {
            let used: i64 = x.iter()
                .filter(|e| e.kind == "expense" && e.category == r.category)
                .map(|e| e.amount).sum();
            json!({"category": r.category, "budget": r.amount, "spent": used, "remaining": r.amount - used})
        }).collect::<Vec<_>>(),
    })))
}
