async fn workload_view(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let matters = visible_matters(&s, &u).await?;
    let mut by_user: std::collections::BTreeMap<String, (i64, i64)> =
        std::collections::BTreeMap::new();
    for m in &matters {
        let team = s
            .stores
            .ops
            .mteam_list(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        let tasks = s
            .stores
            .core
            .list_tasks(&u.claims.org, m.id)
            .await
            .map_err(map_store)?;
        let open_tasks = tasks.iter().filter(|t| t.status == "open").count() as i64;
        for t in team {
            let e = by_user.entry(t.user_id).or_insert((0, 0));
            e.0 += 1;
            e.1 += open_tasks;
        }
    }
    let rows: Vec<Value> = by_user
        .into_iter()
        .map(|(user, (matters, open_tasks))| {
            json!({"user_id": user, "matters": matters, "open_tasks": open_tasks})
        })
        .collect();
    Ok(Json(json!(rows)))
}
