#[derive(Debug, Deserialize, Validate)]
struct MtplReq {
    #[validate(length(min = 1, max = 160))]
    name: String,
    #[validate(length(max = 500))]
    description: Option<String>,
    #[validate(length(min = 1, max = 4000))]
    tasks_json: String,
}
async fn mtpl_add(
    State(s): State<FullState>,
    headers: HeaderMap,
    Json(b): Json<MtplReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    // Array shape re-checked here so malformed payloads surface as 409
    // (store is the source of truth; this keeps the error contract stable).
    let tasks: Vec<String> = serde_json::from_str(b.tasks_json.trim())
        .map_err(|_| AppError::Conflict("tasks_json".into()))?;
    if tasks.is_empty()
        || tasks.len() > 50
        || tasks.iter().any(|t| t.trim().is_empty() || t.len() > 200)
    {
        return Err(AppError::Conflict("tasks_json".into()));
    }
    let desc = b.description.as_deref().unwrap_or("");
    let id = s
        .stores
        .ops
        .mtpl_add(
            &u.claims.org,
            b.name.trim(),
            desc.trim(),
            b.tasks_json.trim(),
        )
        .await
        .map_err(map_store)?;
    Ok(Json(json!({"id": id})))
}
async fn mtpl_list(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let v = s
        .stores
        .ops
        .mtpl_list(&u.claims.org)
        .await
        .map_err(map_store)?;
    Ok(Json(json!(v
        .iter()
        .map(|r| json!({"id": r.id, "name": r.name, "description": r.description, "tasks_json": r.tasks_json}))
        .collect::<Vec<_>>())))
}
#[derive(Debug, Deserialize, Validate)]
struct MtplUseReq {
    #[validate(length(min = 1, max = 300))]
    title: Option<String>,
}
async fn mtpl_instantiate(
    State(s): State<FullState>,
    headers: HeaderMap,
    Path(id): Path<i64>,
    Json(b): Json<MtplUseReq>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::Create)?;
    b.validate()
        .map_err(|e| AppError::Validation(e.to_string()))?;
    let tpl = s
        .stores
        .ops
        .mtpl_get(&u.claims.org, id)
        .await
        .map_err(map_store)?;
    let tasks: Vec<String> = serde_json::from_str(tpl.tasks_json.trim())
        .map_err(|_| AppError::Internal(anyhow::anyhow!("template tasks corrupt")))?;
    let title = b.title.as_deref().unwrap_or(tpl.name.as_str());
    let number = format!("M-{}", uuid::Uuid::new_v4().to_string()[..8].to_uppercase());
    let m: MatterRow = s
        .stores
        .core
        .create_matter(&u.claims.org, None, &number, title.trim())
        .await
        .map_err(|e| AppError::Internal(anyhow::anyhow!(e.to_string())))?;
    for t in &tasks {
        s.stores
            .ops
            .mclose_add(&u.claims.org, m.id, t.trim())
            .await
            .map_err(map_store)?;
    }
    audit(
        &s.pool,
        &s.stores,
        AuditEvent {
            tenant_id: u.claims.org.clone(),
            actor_id: Some(u.claims.sub.clone()),
            action: "matter.instantiated".into(),
            entity: "matter".into(),
            entity_id: m.id,
            ip: None,
        },
    )
    .await;
    Ok(Json(
        json!({"id": m.id, "number": m.number, "tasks": tasks.len()}),
    ))
}
