// ---------- portal slice: SLA display ----------
// SLA display (F-D19-034): the client's own matters with task timeliness —
// overdue vs due-soon vs on-track counts plus the offending rows. Derived
// from the same task due data as the staff SLA export, scoped to the
// portal identity.
async fn portal_sla(
    State(s): State<FullState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    let (org, cid) = portal_client(&headers, &s).await?;
    let map_e =
        |e: legalrust_database::StoreError| AppError::Internal(anyhow::anyhow!(e.to_string()));
    let matters = s.stores.core.list_matters(&org).await.map_err(map_e)?;
    let now = chrono::Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M")
        .to_string();
    let soon = (chrono::Utc::now().naive_utc() + chrono::Duration::days(3))
        .format("%Y-%m-%d %H:%M")
        .to_string();
    let mut overdue = Vec::new();
    let mut due_soon = Vec::new();
    let mut on_track = 0i64;
    for m in matters.iter().filter(|m| m.client_id == Some(cid)) {
        let tasks = s.stores.core.list_tasks(&org, m.id).await.map_err(map_e)?;
        for t in tasks.iter().filter(|t| t.status != "done") {
            match t.due.as_deref() {
                Some(d) if d < now.as_str() => overdue.push(json!({"matter_id": m.id, "matter_title": m.title, "task": t.title, "due": d, "status": t.status})),
                Some(d) if d <= soon.as_str() => due_soon.push(json!({"matter_id": m.id, "matter_title": m.title, "task": t.title, "due": d, "status": t.status})),
                _ => on_track += 1,
            }
        }
    }
    Ok(Json(json!({
        "overdue": overdue, "due_soon": due_soon, "on_track": on_track,
        "breached": !overdue.is_empty(),
    })))
}
// ---------- end portal slice: SLA ----------

