fn pev_counts(v: &[legalrust_database::PortalEventRow]) -> std::collections::BTreeMap<String, i64> {
    let mut m = std::collections::BTreeMap::new();
    for r in v {
        *m.entry(r.kind.clone()).or_insert(0) += 1;
    }
    m
}
