// ---------- approval slice: trend + mobile inbox ----------
// Approval trend (F-D09-027): daily buckets of approval.* audit actions over
// a bounded window (audit trail keeps the last 500 rows; honest window, no
// fabricated history).
#[derive(Debug, Deserialize)]
struct TrendQ {
    days: Option<i64>,
}
async fn approval_trend(
    State(s): State<FullState>,
    headers: HeaderMap,
    Query(q): Query<TrendQ>,
) -> Result<Json<Value>, AppError> {
    let u = auth_user(&headers, &s).await?;
    authorize(&u, Permission::View)?;
    let days = q.days.unwrap_or(30).clamp(1, 90);
    let cutoff = (chrono::Utc::now().naive_utc().date() - chrono::Duration::days(days - 1))
        .format("%Y-%m-%d")
        .to_string();
    let rows = s
        .stores
        .ops
        .audit_list(&u.claims.org, None, None, 500)
        .await
        .map_err(map_store)?;
    let mut days_map: std::collections::BTreeMap<String, (i64, i64, i64)> =
        std::collections::BTreeMap::new();
    for a in rows.iter().filter(|a| a.action.starts_with("approval.")) {
        let d: String = a.created.chars().take(10).collect();
        if d.as_str() < cutoff.as_str() {
            continue;
        }
        let e = days_map.entry(d).or_insert((0, 0, 0));
        e.0 += 1;
        if a.action.ends_with(".approved") || a.action == "approval.bulk_decided" {
            e.1 += 1;
        }
        if a.action.ends_with(".rejected") {
            e.2 += 1;
        }
    }
    let out: Vec<Value> = days_map
        .into_iter()
        .map(|(d, (n, ok, no))| json!({"date": d, "events": n, "approved": ok, "rejected": no}))
        .collect();
    Ok(Json(
        json!({"days": days, "window_days": out.len(), "rows": out}),
    ))
}
